//! The TS log's own outputs (tests/spec/log-vectors.json, regenerated by
//! tests/spec/log-vectors.ts) reproduced byte for byte by aac-log.
#![allow(clippy::unwrap_used, missing_docs)]
use aac_log::{Extra, Level, Log, LogConfig, RequestLog};
use serde_json::{Map, Value};

fn vectors() -> Value {
    serde_json::from_str(include_str!("../../../tests/spec/log-vectors.json")).unwrap()
}

fn level(word: &str) -> Level {
    match word {
        "error" => Level::Error,
        "warn" => Level::Warn,
        "info" => Level::Info,
        _ => Level::Debug,
    }
}

/// The generator's `normalized`: ids, clocks, pids and run ids replaced.
fn normalized(mut entry: Value) -> String {
    entry["id"] = "<id>".into();
    entry["timestamp"] = "<time>".into();
    entry["processId"] = 0.into();
    entry["runId"] = "<run>".into();
    if entry.get("requestId").is_some() {
        entry["requestId"] = "<request>".into();
    }
    if let Some(context) = entry.get_mut("context").and_then(Value::as_object_mut) {
        if context.contains_key("requestId") {
            context.insert("requestId".into(), "<request>".into());
        }
        if context.get("durationMs").is_some_and(Value::is_number) {
            context.insert("durationMs".into(), 0.into());
        }
    }
    serde_json::to_string(&entry).unwrap()
}

#[test]
fn strings_contexts_argv_and_urls_match_the_ts_redaction() {
    let v = vectors();
    for pair in v["mask"].as_array().unwrap() {
        assert_eq!(
            aac_log::mask_secret_tokens(pair[0].as_str().unwrap()),
            pair[1].as_str().unwrap(),
            "{}",
            pair[0]
        );
    }
    for pair in v["context"].as_array().unwrap() {
        let redacted = aac_log::redact_context(pair[0].as_object().unwrap());
        // Byte equality: key order included.
        assert_eq!(
            serde_json::to_string(&redacted).unwrap(),
            serde_json::to_string(&pair[1]).unwrap()
        );
    }
    for pair in v["error"].as_array().unwrap() {
        assert_eq!(aac_log::redact_value(&pair[0]), pair[1]);
    }
    for pair in v["argv"].as_array().unwrap() {
        let argv: Vec<String> = serde_json::from_value(pair[0].clone()).unwrap();
        let want: Vec<String> = serde_json::from_value(pair[1].clone()).unwrap();
        assert_eq!(aac_log::redact_argv(&argv), want, "{argv:?}");
    }
    for pair in v["url"].as_array().unwrap() {
        assert_eq!(
            aac_log::scrub_logged_url(pair[0].as_str().unwrap()),
            pair[1].as_str().unwrap(),
            "{}",
            pair[0]
        );
    }
}

#[test]
fn whole_entries_match_the_ts_logger() {
    let v = vectors();
    let log = Log::new(std::env::temp_dir());
    let mut written = 0;
    for case in v["entries"].as_array().unwrap() {
        let config = LogConfig {
            redact: case["redact"].as_bool().unwrap(),
            level: Some(level(case["configuredLevel"].as_str().unwrap())),
            ..LogConfig::default()
        };
        let entry_level = level(case["level"].as_str().unwrap());
        let passes = (entry_level as u8) <= (config.level.unwrap() as u8);
        assert_eq!(case["line"].is_string(), passes, "{case}");
        if !passes {
            continue;
        }
        let extra = case.get("extra").map_or_else(Extra::default, |e| Extra {
            request_id: None,
            stage: e["stage"].as_str().map(str::to_owned),
            latency_ms: e["latencyMs"].as_f64(),
            error: e.get("error").cloned(),
        });
        let entry = log.entry(
            &config,
            case["source"].as_str().unwrap(),
            entry_level,
            case["event"].as_str().unwrap(),
            case["message"].as_str().unwrap(),
            case["context"].as_object().unwrap_or(&Map::new()),
            &extra,
        );
        assert_eq!(
            normalized(Value::Object(entry)),
            case["line"].as_str().unwrap()
        );
        written += 1;
    }
    assert!(written >= 10);
}

#[test]
fn request_lines_match_the_ts_middleware() {
    let v = vectors();
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(
        dir.path().join("config.yaml"),
        "version: 10\nlogging:\n  level: info\n  redact: true\n",
    )
    .unwrap();
    let log = Log::new(dir.path().to_path_buf());
    let current = dir.path().join("logs/current.jsonl");
    for case in v["requests"].as_array().unwrap() {
        let _ = std::fs::remove_file(&current);
        log.request_completed(&RequestLog {
            request_id: "00000000-0000-4000-8000-000000000000",
            method: "GET",
            url: case["url"].as_str().unwrap(),
            status: case["status"].as_u64().unwrap() as u16,
            duration_ms: 3,
            remote_address: case["remoteAddress"].as_str(),
            via: None,
            user_agent: case["userAgent"].as_str(),
        });
        let line = std::fs::read_to_string(&current).ok();
        match case["line"].as_str() {
            None => assert!(line.is_none(), "{case}"),
            Some(want) => {
                let got: Value = serde_json::from_str(line.unwrap().trim()).unwrap();
                assert_eq!(normalized(got), want);
            }
        }
    }
}
